class Solution:
    def insertIntoMaxTree(self, root: Optional[TreeNode], val: int) -> Optional[TreeNode]:
        a = []
        def inorder(node):
            if node:
                inorder(node.left)
                a.append(node.val)
                inorder(node.right)
        inorder(root)
        a.append(val)
        stack = []
        for x in a:
            node = TreeNode(x)
            last = None
            while stack and stack[-1].val < x:
                last = stack.pop()
            node.left = last
            if stack:
                stack[-1].right = node
            stack.append(node)
        return stack[0]

