public:
    TreeNode* insertIntoMaxTree(TreeNode* root, int val) {
        vector<int> a;
        function<void(TreeNode*)> inorder = [&](TreeNode* n) {
            if (!n) return;
            inorder(n->left);
            a.push_back(n->val);
            inorder(n->right);
        };
        inorder(root);
        a.push_back(val);
        vector<TreeNode*> st;
        for (int x : a) {
            TreeNode* node = new TreeNode(x);
            TreeNode* last = nullptr;
            while (!st.empty() && st.back()->val < x) {
                last = st.back();
                st.pop_back();
            }
            node->left = last;
            if (!st.empty()) st.back()->right = node;
            st.push_back(node);
        }
        return st[0];
    }
};

