class Solution {
    public TreeNode insertIntoMaxTree(TreeNode root, int val) {
        List<Integer> a = new ArrayList<>();
        inorder(root, a);
        a.add(val);
        Deque<TreeNode> st = new ArrayDeque<>();
        TreeNode first = null;
        for (int x : a) {
            TreeNode node = new TreeNode(x), last = null;
            while (!st.isEmpty() && st.peek().val < x) {
                last = st.pop();
            }
            node.left = last;
            if (!st.isEmpty()) st.peek().right = node;
            st.push(node);
        }
        while (st.size() > 1) st.pop();
        return st.peek();
    }
    private void inorder(TreeNode n, List<Integer> a) {
        if (n == null) return;
        inorder(n.left, a);
        a.add(n.val);
        inorder(n.right, a);
    }
}

